import React, { useState, useEffect } from "react";
import {
  Modal,
  Button,
  Table,
  Form,
  Row,
  Col,
  Badge,
  Alert,
} from "@themesberg/react-bootstrap";
import { securedAxiosInstance } from "../../../axiosConfig";
import toast from "react-hot-toast";
import { LoadingCircle } from "../../components/icons";

const DROP_RULES = {
  "BTech(Final year)": { maxCredits: 8, maxSubjects: 2 },
  "BTech(Pre-Final Year)": { maxCredits: 4, maxSubjects: 1 },
  MTech: { maxCredits: 4, maxSubjects: 1 },
  BBA: { maxCredits: 4, maxSubjects: 1 },
  MBA: { maxCredits: 4, maxSubjects: 1 },
  MA: { maxCredits: 4, maxSubjects: 1 },
  MSc: { maxCredits: 4, maxSubjects: 1 },
  BDesign: { maxCredits: 8, maxSubjects: 2 },
};

function findBTechCourseType(batch) {
  const currentDate = new Date();
  const currentMonth = currentDate.getMonth() + 1;
  const currentYear = currentDate.getFullYear();

  const academicYear = currentMonth >= 4 ? currentYear : currentYear - 1;

  const yearsUntilGraduation = batch - academicYear;

  if (
    yearsUntilGraduation <= 1 ||
    (yearsUntilGraduation === 2 && currentMonth >= 4)
  ) {
    return "BTech(Final year)";
  } else if (
    yearsUntilGraduation === 2 ||
    (yearsUntilGraduation === 3 && currentMonth >= 4)
  ) {
    return "BTech(Pre-Final Year)";
  }
  return null;
}

function calculateOptimalCGPA(courseType, courseWiseData) {
  if (!DROP_RULES[courseType]) {
    throw new Error("Invalid course type");
  }

  const { maxCredits, maxSubjects } = DROP_RULES[courseType];

  const courses = courseWiseData
    .map((course) => ({
      ...course,
      credits: parseInt(course.credits) || 0,
      creditPoints: parseInt(course.creditPoints) || 0,
    }))
    .filter((course) => course.credits > 0);

  const sortedCourses = [...courses].sort(
    (a, b) => a.creditPoints / a.credits - b.creditPoints / b.credits
  );

  const calculateCGPA = (includedCourses) => {
    const totalCreditPoints = includedCourses.reduce(
      (sum, course) => sum + course.creditPoints,
      0
    );
    const totalCredits = includedCourses.reduce(
      (sum, course) => sum + course.credits,
      0
    );
    return totalCredits ? totalCreditPoints / totalCredits : 0;
  };

  let bestCGPA = calculateCGPA(courses);
  let droppedCourses = [];
  let remainingCourses = [...courses];

  const canDropMore = (dropped, creditsDropped) => {
    return (
      dropped.length < maxSubjects &&
      creditsDropped + sortedCourses[0]?.credits <= maxCredits
    );
  };

  let currentDropped = [];
  let currentCreditsDropped = 0;

  for (const course of sortedCourses) {
    if (canDropMore(currentDropped, currentCreditsDropped)) {
      currentDropped.push(course);
      currentCreditsDropped += course.credits;

      const remainingCourseSet = courses.filter(
        (c) =>
          !currentDropped.some((dropped) => dropped.courseCode === c.courseCode)
      );

      const newCGPA = calculateCGPA(remainingCourseSet);

      if (newCGPA > bestCGPA) {
        bestCGPA = newCGPA;
        droppedCourses = [...currentDropped];
        remainingCourses = [...remainingCourseSet];
      }
    } else {
      break;
    }
  }

  return {
    droppedCourses: droppedCourses.map((course) => ({
      courseCode: course.courseCode,
      courseTitle: course.courseTitle,
      credits: course.credits,
      gradeLetter: course.gradeLetter,
    })),
  };
}

export function DropSubjects({
  show,
  handleClose,
  allSemGPA,
  batch,
  degree,
  cgpa_before_drop,
}) {
  const courseWiseData = allSemGPA.courseWiseData;
  const [isLoading, setIsLoading] = useState(false);
  const [selectedCourses, setSelectedCourses] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [recommendedCourses, setRecommendedCourses] = useState([]);
  const [error, setError] = useState("");
  const [currentCGPA, setCurrentCGPA] = useState(cgpa_before_drop);

  const courseType = degree === "BTech" ? findBTechCourseType(batch) : degree;
  if (!courseType) {
    setError("Unable to determine course type");
  }
  const dropCriteria = DROP_RULES[courseType];

  // Filter out 0 credit courses and calculate course-wise CGPA
  const filteredCourses = courseWiseData
    .filter((course) => parseInt(course.credits) > 0)
    .map((course) => ({
      ...course,
      cgpa: (parseInt(course.creditPoints) / parseInt(course.credits)).toFixed(
        2
      ),
    }));

  const totalCreditsSelected = selectedCourses.reduce((sum, code) => {
    const course = filteredCourses.find((c) => c.courseCode === code);
    return sum + (course ? parseInt(course.credits) : 0);
  }, 0);

  const handleCourseSelect = (courseCode) => {
    if (selectedCourses.includes(courseCode)) {
      setSelectedCourses(selectedCourses.filter((code) => code !== courseCode));
    } else {
      if (selectedCourses.length >= dropCriteria.maxSubjects) {
        setError("Maximum subjects limit reached");
        return;
      }
      if (
        totalCreditsSelected +
          parseInt(
            filteredCourses.find((c) => c.courseCode === courseCode).credits
          ) >
        dropCriteria.maxCredits
      ) {
        setError("Maximum credits limit reached");
        return;
      }
      setSelectedCourses([...selectedCourses, courseCode]);
    }
    setError("");
  };

  const handleGetRecommendations = () => {
    const optimal = calculateOptimalCGPA(courseType, filteredCourses);
    if (optimal) {
      setRecommendedCourses(
        optimal.droppedCourses.map((course) => course.courseCode)
      );
      setSelectedCourses(
        optimal.droppedCourses.map((course) => course.courseCode)
      );
    }
  };

  const handleSubmit = async () => {
    try {
      setIsLoading(true);
      const res = await securedAxiosInstance.post(
        "/students/drop",
        {
          courses: selectedCourses,
        },
        { withCredentials: true }
      );
      setIsLoading(false);

      if (res.data.success) {
        toast.success(
          "Courses dropped successfully, refresh the page to see changes."
        );
        handleClose();
      } else {
        toast.error(res.data.message);
      }
    } catch (error) {
      toast.error("Something went wrong, please try again later");
    }
  };

  useEffect(() => {
    const calculateCGPA = (droppedCourses) => {
      let totalCredits = 0;
      let totalCreditPoints = 0;
      console.log(droppedCourses);
      courseWiseData.forEach((course) => {
        if (!droppedCourses.find((dc) => dc === course.courseCode)) {
          const credits = parseInt(course.credits);
          const creditPoints = parseInt(course.creditPoints);
          totalCredits += credits;
          totalCreditPoints += creditPoints;
        }
      });

      return totalCredits > 0
        ? (totalCreditPoints / totalCredits).toFixed(2)
        : 0;
    };

    const newCGPA = calculateCGPA(selectedCourses);
    console.log(newCGPA);
    setCurrentCGPA(newCGPA);
  }, [selectedCourses, courseWiseData]);

  return (
    <Modal show={show} onHide={handleClose} size="lg">
      <Modal.Header closeButton>
        <Modal.Title>Drop Subjects</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <p className="text-muted">
          Select subjects to drop according to your program criteria. Maximum{" "}
          {dropCriteria.maxCredits} credits and {dropCriteria.maxSubjects}{" "}
          subjects allowed.
        </p>

        {error && <Alert variant="danger">{error}</Alert>}

        <Row className="mb-3 align-items-center">
          <Col>
            <Badge bg="secondary" className="me-2">
              Selected: {selectedCourses.length}/{dropCriteria.maxSubjects}{" "}
              subjects
            </Badge>
            <Badge bg="secondary">
              Credits: {totalCreditsSelected}/{dropCriteria.maxCredits}
            </Badge>
            <div className="mt-3">
              <strong>CGPA after dropping selected courses: </strong>
              {currentCGPA}
            </div>
          </Col>
          <Col xs="auto">
            <Button
              variant="outline-primary"
              onClick={handleGetRecommendations}
            >
              Get Recommendations
            </Button>
          </Col>
        </Row>

        <Form.Control
          type="text"
          placeholder="Search courses..."
          className="mb-3"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />

        <div
          className="table-responsive"
          style={{ maxHeight: "60vh", overflowY: "auto" }}
        >
          <Table striped bordered hover>
            <thead className="sticky-top bg-white">
              <tr>
                <th style={{ width: "40px" }}></th>
                <th>Code</th>
                <th>Title</th>
                <th>Type</th>
                <th>Credits</th>
                <th>Grade</th>
                <th>CGPA</th>
              </tr>
            </thead>
            <tbody>
              {filteredCourses
                .filter(
                  (course) =>
                    course.courseCode
                      .toLowerCase()
                      .includes(searchTerm.toLowerCase()) ||
                    course.courseTitle
                      .toLowerCase()
                      .includes(searchTerm.toLowerCase())
                )
                .map((course) => (
                  <tr
                    key={course.courseCode}
                    className={
                      recommendedCourses.includes(course.courseCode)
                        ? "table-info"
                        : ""
                    }
                  >
                    <td>
                      <Form.Check
                        type="checkbox"
                        disabled={isLoading}
                        checked={selectedCourses.includes(course.courseCode)}
                        onChange={() => handleCourseSelect(course.courseCode)}
                      />
                    </td>
                    <td>{course.courseCode}</td>
                    <td>{course.courseTitle}</td>
                    <td>{course.courseType}</td>
                    <td>{course.credits}</td>
                    <td>{course.gradeLetter}</td>
                    <td>{course.cgpa}</td>
                  </tr>
                ))}
            </tbody>
          </Table>
        </div>
      </Modal.Body>
      <Modal.Footer>
        <Button variant="secondary" onClick={handleClose}>
          Cancel
        </Button>
        <Button
          variant="primary"
          disabled={selectedCourses.length === 0 || isLoading}
          onClick={() => {
            handleSubmit();
          }}
        >
          {isLoading ? <LoadingCircle /> : "Confirm Drop"}
        </Button>
      </Modal.Footer>
    </Modal>
  );
}
